// QA-2 (auth): the AC-5 admin-token matrix driven through the REAL api.New
// router against a real temp store. The coder's middleware_test.go covers the
// {no-header, wrong-scheme=Basic, wrong-token, correct} core cases at the
// middleware unit altitude. This test adds the EDGE failure modes the coder's
// matrix omits — the "Token " scheme (named in the QA task), case-sensitivity
// of the "Bearer" prefix (bearer/BEARER), and a whitespace-only credential —
// AND asserts the side effect through the full router + store: every miss
// creates NO library row (the domain call is truly gated). That is a genuinely
// different failure-mode set and a higher altitude than the coder's test, so it
// is not redundant.
package mellifera_test

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"testing"

	"github.com/mellifera/mellifera/internal/api"
	"github.com/mellifera/mellifera/internal/scan"
	"github.com/mellifera/mellifera/internal/store"
)

// TestQA_Auth_AdminTokenMatrix exercises seam S8 (admin middleware -> Principal)
// end-to-end through the real router. Every non-canonical Authorization header
// MUST yield 401 + the canonical "unauthenticated" body AND create no library;
// only an exact "Bearer <token>" match yields 201 and a row.
func TestQA_Auth_AdminTokenMatrix(t *testing.T) {
	const token = "qa-secret-admin-token"
	st := qaOpenStore(t)
	// The create-library handler is the only domain call hit here; Scan is never
	// invoked, so a fail-loud stub is the safest injection.
	handler := api.New(api.Deps{
		AdminToken: token,
		Store:      st,
		Scan: func(context.Context, int64) (scan.Result, error) {
			t.Errorf("Scan must not run during the auth matrix")
			return scan.Result{}, nil
		},
	})

	cases := []struct {
		name       string
		auth       string // raw Authorization header value ("" = omit header)
		wantStatus int
	}{
		// Coder-covered core (re-asserted at router altitude for the side effect).
		{"no_header", "", http.StatusUnauthorized},
		{"wrong_token", "Bearer " + token + "-wrong", http.StatusUnauthorized},
		{"correct_token", "Bearer " + token, http.StatusCreated},

		// QA edge cases the coder's matrix omits.
		{"token_scheme_not_bearer", "Token " + token, http.StatusUnauthorized}, // QA task-named
		{"basic_scheme", "Basic dXNlcjpwYXNz", http.StatusUnauthorized},
		{"lowercase_bearer_prefix", "bearer " + token, http.StatusUnauthorized}, // case-sensitive prefix
		{"uppercase_bearer_prefix", "BEARER " + token, http.StatusUnauthorized}, // case-sensitive prefix
		{"empty_credential", "Bearer ", http.StatusUnauthorized},                // scheme ok, no secret
		{"credential_is_only_whitespace", "Bearer    ", http.StatusUnauthorized},
		{"malformed_no_space", "Bearertoken", http.StatusUnauthorized},
	}

	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			before := qaLibraryCount(t, st)
			body := []byte(`{"module_id":"tv","root_path":"/qa/auth","display_name":"QA Auth"}`)
			req := httptest.NewRequest(http.MethodPost, "/api/v1/libraries", bytes.NewReader(body))
			req.Header.Set("Content-Type", "application/json")
			if tc.auth != "" {
				req.Header.Set("Authorization", tc.auth)
			}
			rec := httptest.NewRecorder()
			handler.ServeHTTP(rec, req)

			if rec.Code != tc.wantStatus {
				t.Fatalf("status = %d, want %d", rec.Code, tc.wantStatus)
			}
			after := qaLibraryCount(t, st)
			if tc.wantStatus == http.StatusUnauthorized {
				// Side effect: the domain call was gated — no library created.
				if after != before {
					t.Fatalf("a 401 created a library row: count %d -> %d", before, after)
				}
				if code := qaErrCode(rec.Result().Body); code != "unauthenticated" {
					t.Fatalf("error code = %q, want unauthenticated (canonical body)", code)
				}
			} else {
				// Correct token: exactly one library was created.
				if after != before+1 {
					t.Fatalf("correct token: library count %d -> %d, want +1", before, after)
				}
			}
		})
	}
}

// qaOpenStore opens a fresh temp SQLite store (WAL + full schema) for QA.
func qaOpenStore(t *testing.T) *store.Store {
	t.Helper()
	s, err := store.Open(context.Background(), filepath.Join(t.TempDir(), "qa.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = s.Close() })
	return s
}

// qaLibraryCount returns the row count of the libraries table via the store's
// shared connection. Parameterized (no value interpolation) — it is a read.
func qaLibraryCount(t *testing.T, s *store.Store) int {
	t.Helper()
	var n int
	if err := s.DB().QueryRowContext(context.Background(),
		"SELECT COUNT(*) FROM libraries").Scan(&n); err != nil {
		t.Fatalf("count libraries: %v", err)
	}
	return n
}

type qaErrorEnvelope struct {
	Error struct {
		Code string `json:"code"`
	} `json:"error"`
}

func qaErrCode(body interface{ Read(p []byte) (int, error) }) string {
	var env qaErrorEnvelope
	_ = json.NewDecoder(body).Decode(&env)
	return env.Error.Code
}
